export function makePatch(source,clean){const out=source.slice();for(let y=0;y<80;y++)for(let x=0;x<100;x++){const r=Math.sqrt(((x-50)/29)**2+((y-42)/27)**2),a=Math.max(0,Math.min(1,(1-r)*6));for(let k=0;k<3;k++){const j=(y*100+x)*4+k;out[j]=Math.round(source[j]*(1-a)+clean[j]*a)}}return out}
export function deformPlant(sprite,worldMs,contacts=[],enabled=true){const out=new Uint8ClampedArray(100*80*4);if(!enabled)return out;let impact=0;for(const c of contacts){const d=Math.hypot(c.contact[0]-970,c.contact[1]-312);if(d<36)impact=Math.max(impact,(1-d/36)*[.15,1,.55,0][c.frame])}const wind=1.8*Math.sin(worldMs*Math.PI*2/3200);function disp(x,y){const dx=x-50,dy=y-44,r=Math.hypot(dx,dy),g=Math.max(0,Math.min(1,(r-5)/15));return [g*(wind+Math.sign(dx)*1.2*impact),g*1.6*impact]}
for(let y=0;y<80;y++)for(let x=0;x<100;x++){let sx=x,sy=y;for(let k=0;k<3;k++){const d=disp(sx,sy);sx=x-d[0];sy=y-d[1]}const x0=Math.floor(sx),y0=Math.floor(sy);if(x0<0||y0<0||x0+1>=100||y0+1>=80)continue;const fx=sx-x0,fy=sy-y0,pts=[[x0,y0,(1-fx)*(1-fy)],[x0+1,y0,fx*(1-fy)],[x0,y0+1,(1-fx)*fy],[x0+1,y0+1,fx*fy]],j=(y*100+x)*4;let alpha=0,colors=[0,0,0];for(const[xx,yy,w]of pts){const i=(yy*100+xx)*4,a=sprite[i+3]/255*w;alpha+=a;for(let k=0;k<3;k++)colors[k]+=sprite[i+k]*a}out[j+3]=Math.round(alpha*255);if(alpha)for(let k=0;k<3;k++)out[j+k]=Math.round(colors[k]/alpha)}return out}
export function overlay(host,patch,sprite,camera){const[cx,cy,w,h]=camera;for(let y=0;y<80;y++)for(let x=0;x<100;x++){const xx=x+920-cx,yy=y+270-cy;if(xx<0||yy<0||xx>=w||yy>=h)continue;const i=(y*100+x)*4,j=(yy*w+xx)*4;host.set(patch.subarray(i,i+4),j)}for(let y=0;y<80;y++)for(let x=0;x<100;x++){const xx=x+920-cx,yy=y+268-cy;if(xx<0||yy<0||xx>=w||yy>=h)continue;const i=(y*100+x)*4,j=(yy*w+xx)*4,a=sprite[i+3]/255;for(let k=0;k<3;k++)host[j+k]=Math.round(host[j+k]*(1-a)+sprite[i+k]*a)}}
